// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport android.app.Activityimport android.content.Contextimport android.provider.Settingsimport android.view.Windowimport android.view.WindowManagerimport com.roshan.persona.common.AppError/** * NOUS — Display Service (Module 10 v2 — Step 10.4). * * Wraps Android display-related APIs (Settings.System for brightness, * WindowManager for keep-screen-on) behind an interface for testability. * * ## Brightness * * Two layers: *  - `Settings.System.SCREEN_BRIGHTNESS` — persisted brightness (0-255), *    survives across reboots. Requires `WRITE_SETTINGS` permission. *  - `WindowManager.LayoutParams.screenBrightness` — immediate window-level *    brightness override (-1 = use system, 0-1 = manual). Doesn't require *    permission but only applies to the current window. * * [BrightnessHandler] writes to **both** — the persisted value so the change * survives, and the window value so it takes effect immediately without * requiring a screen re-init. * * ## Auto-brightness * * `Settings.System.SCREEN_BRIGHTNESS_MODE`: *  - 0 = manual (user controls brightness) *  - 1 = automatic (sensor-driven) * * When setting an explicit brightness, the handler temporarily disables * auto-brightness (otherwise the system would override the user's choice). * * ## Keep-screen-on * * `WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON` — applied to a specific * [Activity]'s window. The handler needs a reference to the current activity * (provided via [ActivityProvider]). */interface DisplayService {    /** Get the current persisted brightness level (0-255). */    fun getBrightness(): Int    /** Set the persisted brightness level (0-255, clamped). */    fun setBrightness(level: Int)    /** True if auto-brightness is enabled. */    fun isAutoBrightness(): Boolean    /** Enable/disable auto-brightness. */    fun setAutoBrightness(enabled: Boolean)    /**     * Apply immediate brightness to the current window.     *     * @param level 0.0–1.0, or null to use system default.     */    fun applyWindowBrightness(level: Float?)    /**     * Toggle "keep screen on" flag for the current activity's window.     *     * @param enabled true to keep screen on, false to allow auto-off.     * @return true if a window was available to apply the flag to.     */    fun setKeepScreenOn(enabled: Boolean): Boolean}/** * Android [DisplayService] backed by [Settings.System] + [WindowManager]. * * @param context       application context (for Settings.System reads/writes). * @param activityProvider returns the current foreground Activity (for window *                          brightness + keep-screen-on), or null if no activity. */class AndroidDisplayService(    private val context: Context,    private val activityProvider: () -> Activity? = { null },) : DisplayService {    override fun getBrightness(): Int = try {        Settings.System.getInt(            context.contentResolver,            Settings.System.SCREEN_BRIGHTNESS,            DEFAULT_BRIGHTNESS,        )    } catch (t: Throwable) {        Timber.tag("AndroidDisplayService").w("Failed to read brightness", t)        DEFAULT_BRIGHTNESS    }    override fun setBrightness(level: Int) {        val clamped = level.coerceIn(0, MAX_BRIGHTNESS)        try {            Settings.System.putInt(                context.contentResolver,                Settings.System.SCREEN_BRIGHTNESS,                clamped,            )        } catch (t: SecurityException) {            Timber.tag("AndroidDisplayService").w("WRITE_SETTINGS not granted", t)            throw t        }    }    override fun isAutoBrightness(): Boolean = try {        Settings.System.getInt(            context.contentResolver,            Settings.System.SCREEN_BRIGHTNESS_MODE,            Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL,        ) == Settings.System.SCREEN_BRIGHTNESS_MODE_AUTOMATIC    } catch (t: Throwable) {        false    }    override fun setAutoBrightness(enabled: Boolean) {        try {            Settings.System.putInt(                context.contentResolver,                Settings.System.SCREEN_BRIGHTNESS_MODE,                if (enabled) Settings.System.SCREEN_BRIGHTNESS_MODE_AUTOMATIC                else Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL,            )        } catch (t: SecurityException) {            Timber.tag("AndroidDisplayService").w("WRITE_SETTINGS not granted for auto-brightness", t)            throw t        }    }    override fun applyWindowBrightness(level: Float?) {        val activity = activityProvider() ?: return        val attrs = activity.window.attributes        attrs.screenBrightness = level ?: WindowManager.LayoutParams.BRIGHTNESS_OVERRIDE_NONE        activity.window.attributes = attrs    }    override fun setKeepScreenOn(enabled: Boolean): Boolean {        val activity = activityProvider() ?: return false        return try {            if (enabled) {                activity.window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)            } else {                activity.window.clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)            }            true        } catch (t: Throwable) {            Timber.tag("AndroidDisplayService").w("Failed to set keep-screen-on", t)            false        }    }    companion object {        const val DEFAULT_BRIGHTNESS = 128        const val MAX_BRIGHTNESS = 255    }}// ──────────────────────────────────────────────────────────────────────────/** * NOUS — Accessibility Service Interface (Module 10 v2 — Review 2 Fix B). * * Minimal interface for the accessibility-service-backed operations Module 10 * needs (currently just screen lock). The real implementation lives in * Module 9 (Agent) — `NousAccessibilityService` extends Android's * `AccessibilityService` and exposes `performGlobalAction` via this interface. * * ## Why not DevicePolicyManager.lockNow()? (Review 2 Fix B) * * `DevicePolicyManager.lockNow()` requires Device Admin. Once used, the device * unlocks with **PIN/password only — biometric (fingerprint/face) is broken**. * This is a UX disaster. The accessibility service's `GLOBAL_ACTION_LOCK_SCREEN` * triggers a normal lock that preserves biometric unlock. * * ## Wiring * * Module 9 (Agent) provides the real `NousAccessibilityService` and binds it * to this interface via Hilt. Until Module 9 ships, Module 10 uses * [NoopAccessibilityService] which returns `false` (screen lock fails with * "Accessibility Service required" message). * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Screen Lock</a> */interface NousAccessibilityServiceInterface {    /** True if the accessibility service is enabled (user granted permission). */    fun isServiceEnabled(): Boolean    /**     * Perform a global accessibility action.     *     * @param action one of `AccessibilityService.GLOBAL_ACTION_*` constants     *               (e.g., `GLOBAL_ACTION_LOCK_SCREEN`, `GLOBAL_ACTION_BACK`,     *               `GLOBAL_ACTION_HOME`, `GLOBAL_ACTION_RECENTS`).     * @return true if the action was performed successfully.     */    fun performGlobalAction(action: Int): Boolean}/** * No-op accessibility service — used until Module 9 ships the real impl. * * Returns `false` for all actions, so handlers fail gracefully with a * user-friendly message ("Enable Accessibility Service in Settings"). */class NoopAccessibilityService : NousAccessibilityServiceInterface {    override fun isServiceEnabled(): Boolean = false    override fun performGlobalAction(action: Int): Boolean = false}// ──────────────────────────────────────────────────────────────────────────/** * Android global accessibility action constants (re-exported for handler use). * * These mirror `AccessibilityService.GLOBAL_ACTION_*` but are duplicated here * so the system module doesn't need a direct dependency on * `android.accessibilityservice.AccessibilityService` (which would pull in * the full accessibility framework). */object AccessibilityActions {    /** Lock the screen (biometric-friendly). */    const val GLOBAL_ACTION_LOCK_SCREEN = 8    /** Go back. */    const val GLOBAL_ACTION_BACK = 1    /** Go home. */    const val GLOBAL_ACTION_HOME = 2    /** Open recents. */    const val GLOBAL_ACTION_RECENTS = 3    /** Open notifications. */    const val GLOBAL_ACTION_NOTIFICATIONS = 4    /** Open quick settings. */    const val GLOBAL_ACTION_QUICK_SETTINGS = 5    /** Take a screenshot (API 28+). */    const val GLOBAL_ACTION_TAKE_SCREENSHOT = 15    /** Dismiss notification shade. */    const val GLOBAL_ACTION_DISMISS_NOTIFICATION_SHADE = 14}